"""Paper numbers generated from logged runs (CLAUDE.md: every number in a paper is generated by
code; never typed by hand).

A paper's builder (e.g. ``vnbank.research.gold.report``) reads the run folders named in its
registry (``research/paperN/configs/report.yaml``), and writes to ``papers/paperN/generated/``:

* ``numbers.tex``: one ``\\newcommand`` per reported number, each with the run and field it came
  from, under a header recording the generating commit and every source run;
* ``tab_*.tex``: booktabs ``tabular`` bodies (the paper wraps them in its own table floats).

Rules enforced here:

* macro names are letters only (LaTeX); digits are spelled out (``macro("p2", "h1")`` -> PTwoHOne);
* a name can be defined once;
* a source run must exist and its recorded commit must not be ``+dirty`` (numbers in a paper
  come only from committed code);
* numbers print with a true minus sign (``\\ensuremath{-0.010}``), fixed decimals, so a macro
  works in text and in math.
"""

from __future__ import annotations

import json
import math
import re
from dataclasses import dataclass, field
from datetime import UTC, datetime
from pathlib import Path

import pandas as pd

from vnbank.common import paths

DIGITS = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
_NAME = re.compile(r"^[A-Za-z]+$")
_LATEX_SPECIAL = {"&": r"\&", "%": r"\%", "$": r"\$", "#": r"\#", "_": r"\_", "{": r"\{",
                  "}": r"\}", "~": r"\textasciitilde{}", "^": r"\textasciicircum{}",
                  "\\": r"\textbackslash{}"}  # fmt: skip


class ReportError(ValueError):
    """A paper number cannot be generated safely (missing or dirty run, bad name, ...)."""


def macro(*parts: str) -> str:
    """CamelCase letters-only macro name; digits are spelled out: ("p2", "h1", "beta5") ->
    "PTwoHOneBetaFive"."""
    out = []
    for p in parts:
        words = re.findall(r"[A-Za-z]+|\d", str(p))
        if not words:
            raise ReportError(f"macro part {p!r} has no letters or digits")
        for w in words:
            w = DIGITS[int(w)] if w.isdigit() else w
            out.append(w[:1].upper() + w[1:])
    name = "".join(out)
    if not _NAME.match(name):
        raise ReportError(f"bad macro name from {parts!r}: {name!r}")
    return name


def num(x: float | None, digits: int = 3, signed: bool = False) -> str:
    """Fixed-decimal number with a true minus sign; NaN/None -> an em dash."""
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return r"\textemdash{}"
    if round(x, digits) == 0:
        x = 0.0  # never print -0.000
    s = f"{x:+.{digits}f}" if signed else f"{x:.{digits}f}"
    return r"\ensuremath{" + s + "}"  # in math mode "-" typesets as a true minus


def interval(lo: float, hi: float, digits: int = 3) -> str:
    """[lo, hi] with true minus signs."""
    a = num(lo, digits).removeprefix(r"\ensuremath{").removesuffix("}")
    b = num(hi, digits).removeprefix(r"\ensuremath{").removesuffix("}")
    return r"\ensuremath{[" + a + ", " + b + "]}"


def integer(n: int) -> str:
    """Thousands separated by a thin space (journal style): 3569 -> 3\\,569."""
    return r"\ensuremath{" + f"{int(n):,}".replace(",", r"\,") + "}"


def escape(text: str) -> str:
    return "".join(_LATEX_SPECIAL.get(c, c) for c in str(text))


@dataclass
class Run:
    """A logged run folder: its config and any JSON files it wrote."""

    path: Path
    config: dict

    @classmethod
    def load(cls, paper: int, name: str, allow_dirty: bool = False) -> Run:
        path = paths.runs_dir(paper) / name
        if not (path / "config.json").exists():
            raise ReportError(f"run {name!r} not found under {paths.runs_dir(paper)}")
        cfg = json.loads((path / "config.json").read_text())
        commit = str(cfg.get("git_commit", ""))
        if not commit:
            raise ReportError(f"run {name!r} records no git commit")
        if commit.endswith("+dirty") and not allow_dirty:
            raise ReportError(f"run {name!r} was made from uncommitted code ({commit})")
        return cls(path, cfg)

    def json(self, file: str) -> dict:
        return json.loads((self.path / file).read_text())

    @property
    def name(self) -> str:
        return self.path.name

    @property
    def commit(self) -> str:
        return str(self.config["git_commit"])[:12]


@dataclass
class Numbers:
    """Collects macros with their sources and writes numbers.tex."""

    paper: int
    entries: list[tuple[str, str, str]] = field(default_factory=list)  # name, value, source
    runs: dict[str, str] = field(default_factory=dict)  # run name -> commit

    def add(self, name: str, value: str, run: Run | None, source: str) -> None:
        if not _NAME.match(name):
            raise ReportError(f"bad macro name {name!r}")
        if any(n == name for n, _, _ in self.entries):
            raise ReportError(f"macro {name!r} defined twice")
        if run is not None:
            self.runs[run.name] = run.commit
            source = f"{run.name}: {source}"
        self.entries.append((name, value, source))

    def render(self, generator: str, commit: str) -> str:
        head = [
            "% GENERATED FILE: do not edit by hand (CLAUDE.md: every number comes from code).",
            f"% generator: {generator}",
            f"% generated at commit {commit} on {datetime.now(UTC):%Y-%m-%d %H:%M UTC}",
            "% source runs:",
            *[f"%   {r} (commit {c})" for r, c in sorted(self.runs.items())],
            "",
        ]
        body = [f"\\newcommand{{\\{n}}}{{{v}}} % {escape(s).replace('%', '')}"
                for n, v, s in self.entries]  # fmt: skip
        return "\n".join(head + body) + "\n"

    def write(self, out_dir: Path, generator: str, commit: str) -> Path:
        out_dir.mkdir(parents=True, exist_ok=True)
        p = out_dir / "numbers.tex"
        p.write_text(self.render(generator, commit))
        return p


def tabular(df: pd.DataFrame, align: str | None = None, header: list[str] | None = None,
            notes: str | None = None) -> str:  # fmt: skip
    """booktabs tabular body. Cells that are already LaTeX (start with a backslash) are kept;
    other text is escaped. The caller formats numbers (num/interval) before passing them."""
    align = align or ("l" + "r" * (df.shape[1] - 1))
    if len(align) != df.shape[1]:
        raise ReportError(f"align {align!r} does not match {df.shape[1]} columns")
    cols = header or [escape(c) for c in df.columns]

    def cell(v) -> str:
        s = str(v)
        return s if s.startswith("\\") else escape(s)

    lines = [f"\\begin{{tabular}}{{{align}}}", r"\toprule", " & ".join(cols) + r" \\",
             r"\midrule"]  # fmt: skip
    lines += [" & ".join(cell(v) for v in row) + r" \\" for row in df.itertuples(index=False)]
    lines.append(r"\bottomrule")
    lines.append(r"\end{tabular}")
    if notes:
        lines.append(f"% notes: {notes}")
    return "\n".join(lines) + "\n"


def write_table(out_dir: Path, name: str, body: str, source: str) -> Path:
    if not re.match(r"^tab_[a-z0-9_]+$", name):
        raise ReportError(f"table name must look like tab_xxx: {name!r}")
    out_dir.mkdir(parents=True, exist_ok=True)
    p = out_dir / f"{name}.tex"
    p.write_text(f"% GENERATED FILE: do not edit by hand. Source: {source}\n" + body)
    return p
